export type UpdateNote = { n: number; text: string };

export type UpdateRelease = { version: string; remark: string; notes: UpdateNote[] };

/** 1.1 đến 1.16, mục kế tiếp là 2.0. Rồi 2.1 đến 2.16, rồi 3.0. */
export function nextVersion(current: string | null): string {
  if (!current) return "1.1";
  const [major, minor] = current.split(".").map(Number);
  if (minor >= 16) return `${major + 1}.0`;
  if (minor === 0) return `${major}.1`;
  return `${major}.${minor + 1}`;
}

